namespace SstvVPrinter.IppProbe.Ipp;

public sealed class IppAttribute : IEquatable<IppAttribute> { public IppAttribute(string name, IReadOnlyList<IppValue> values) { ArgumentException.ThrowIfNullOrEmpty(name); if (values.Count == 0) throw new ArgumentException(nameof(values)); Name = name; Values = values.ToArray(); } public string Name { get; } public IReadOnlyList<IppValue> Values { get; } public bool Equals(IppAttribute? o) => o is not null && Name == o.Name && Values.SequenceEqual(o.Values); public override bool Equals(object? o) => Equals(o as IppAttribute); public override int GetHashCode() => Values.Aggregate(Name.GetHashCode(StringComparison.Ordinal), HashCode.Combine); }
public sealed class IppAttributeGroup : IEquatable<IppAttributeGroup> { public IppAttributeGroup(byte tag, IReadOnlyList<IppAttribute> attributes) { Tag = tag; Attributes = attributes.ToArray(); } public byte Tag { get; } public IReadOnlyList<IppAttribute> Attributes { get; } public bool Equals(IppAttributeGroup? o) => o is not null && Tag == o.Tag && Attributes.SequenceEqual(o.Attributes); public override bool Equals(object? o) => Equals(o as IppAttributeGroup); public override int GetHashCode() => Attributes.Aggregate(Tag.GetHashCode(), HashCode.Combine); }
